mapper.select:

where exam_id = #{examId}
  and student_id = #{studentId}
  and question_id = #{questionId}
order by answer_id desc
limit 1


where grader_id = #{graderId}

    and grading_status = #{gradingStatus}

order by answer_id asc

select a.answer_id as answerId, a.exam_id as examId, e.exam_name as examName, a.question_id as questionId, pq.question_content as questionContent, pq.question_score as questionScore, a.student_answer as studentAnswer, a.score as score, a.grading_status as gradingStatus, a.preview_status as previewStatus, a.preview_path as previewPath, a.preview_error_message as previewErrorMessage from biz_county_exam_answer a inner join biz_county_exam e on a.exam_id = e.exam_id inner join biz_county_exam_paper_question pq on pq.exam_id = a.exam_id and pq.student_id = a.student_id and pq.question_id = a.question_id where a.grader_id = #{graderId} and pq.question_type = 'practical' and e.status = '2' and ifnull(e.grading_enabled, '0') = '1'
and a.grading_status = #{gradingStatus}
order by e.exam_id desc, a.answer_id asc

mapper.update:
update biz_county_exam_answer
student_answer = #{studentAnswer}, score = #{score}, is_correct = #{isCorrect}, grader_id = #{graderId}, grading_status = #{gradingStatus}, answer_time = #{answerTime}, file_path = #{filePath}, submit_time = #{submitTime}, typing_speed = #{typingSpeed}, accuracy_rate = #{accuracyRate}, completion_rate = #{completionRate}, preview_status = #{previewStatus}, preview_path = #{previewPath}, preview_retry_count = #{previewRetryCount}, preview_last_retry_time = #{previewLastRetryTime}, preview_error_message = #{previewErrorMessage},
where answer_id = #{answerId}

update biz_county_exam_answer set student_answer = #{studentAnswer}, score = #{score}, is_correct = #{isCorrect}, answer_time = #{answerTime}, file_path = #{filePath}, submit_time = #{submitTime}, typing_speed = #{typingSpeed}, accuracy_rate = #{accuracyRate}, completion_rate = #{completionRate}, preview_status = #{previewStatus}, preview_path = #{previewPath}, preview_retry_count = #{previewRetryCount}, preview_last_retry_time = #{previewLastRetryTime}, preview_error_message = #{previewErrorMessage}
, grading_status = #{gradingStatus}
where answer_id = #{answerId}

update biz_county_exam_answer a
inner join biz_county_exam e on e.exam_id = a.exam_id
set a.score = #{score},
    a.grading_status = '1',
    a.grader_id = #{graderId}
where a.answer_id = #{answerId}
  and a.grader_id = #{graderId}
  and e.status = '2'
  and ifnull(e.grading_enabled, '0') = '1'
  and e.del_flag = '0'

update biz_county_exam_answer
set preview_status = 'converting',
    preview_path = null,
    preview_retry_count = #{nextRetryCount},
    preview_last_retry_time = #{claimedAt},
    preview_error_message = null
where answer_id = #{answerId}
  and preview_path is null
  and preview_status = #{expectedStatus}
  and ifnull(preview_retry_count, 0) = #{expectedRetryCount}
  and (
        (#{expectedLastRetryTime} is null and preview_last_retry_time is null)
     or preview_last_retry_time = #{expectedLastRetryTime}
  )
